// Scan every PLC and emit its raw holding registers, the way a Modbus
// poll would see them. Nothing here is in engineering units.
const plants = global.get('sim_plants');
const now = Date.now();
const out = [];
for (const p of Object.values(plants)) {
    if (p.forced === 'jam') { p.state = 3; p.fault = 2104; p.forced = null; }
    if (p.forced === 'starve') { p.state = 2; p.fault = 3310; p.idleUntil = now + 45000; p.forced = null; }

    // Micro-stops: the line starves for a few seconds and recovers by itself.
    if (p.state === 1 && Math.random() < 0.012) { p.state = 2; p.fault = 3310; p.idleUntil = now + 8000 + Math.random() * 12000; }
    if (p.state === 2 && p.idleUntil && now > p.idleUntil) { p.state = 1; p.fault = 0; p.idleUntil = 0; }

    if (p.state === 1) {
        p.speed += (p.target - p.speed) * 0.3 + (Math.random() - 0.5) * p.target * 0.02;
        const made = p.speed / 30;                       // bottles in a 2 s scan
        const rej = Math.random() < (made * p.rejRate % 1) ? Math.ceil(made * p.rejRate) : Math.floor(made * p.rejRate);
        p.good += Math.round(made) - rej;
        p.reject += rej;
        p.tempC += (4.2 - p.tempC) * 0.2 + (Math.random() - 0.5) * 0.15;
    } else {
        p.speed = Math.max(0, p.speed * 0.3);
        p.tempC += p.state === 3 ? 0.05 : 0.01;          // product warms while the line is down
    }

    const good = p.good >>> 0, hi = good >>> 16, lo = good & 0xFFFF;
    let regs;
    if (p.map === 'LEGACY_F') {
        const legacyState = { 0: 0, 1: 10, 2: 20, 3: 30 }[p.state];
        regs = [legacyState, Math.round((p.tempC * 9 / 5 + 32) * 10), Math.round(p.speed), lo, hi, p.reject & 0xFFFF, p.fault];
    } else {
        regs = [p.state, Math.round(p.tempC * 10), Math.round(p.speed), hi, lo, p.reject & 0xFFFF, p.fault];
    }
    out.push({ topic: 'plc/' + p.site, payload: { site: p.site, line: p.line, plcModel: p.plc, map: p.map, regs, ts: now } });
}
return [out];

