// Operator commands arriving from the Edge HMI.
const plants = global.get('sim_plants');
const { site, cmd, value } = msg.payload || {};
const p = plants && plants[site];
if (!p) return null;
if (cmd === 'clear_fault') { p.state = 1; p.fault = 0; p.idleUntil = 0; }
if (cmd === 'set_speed' && Number.isFinite(value)) p.target = Math.max(0, Math.min(800, value));
node.status({ fill: 'blue', shape: 'dot', text: `${site} ${cmd} @ ${new Date().toISOString().slice(11, 19)}` });
return null;

// Emit SAP ORDERS05 IDocs (JSON-serialised) the way an SAP PI/PO or
// Integration Suite adapter would hand them over.
const CUSTOMERS = [
    { id: '0000100231', name: 'Harbor Grocers' },
    { id: '0000100477', name: 'Mesa Foodservice' },
    { id: '0000100912', name: 'Northline Distribution' },
    { id: '0000101206', name: 'Coastal Mart' },
    { id: '0000101388', name: 'Summit Wholesale' },
];
const MATERIALS = [
    { id: 'FG-1001', desc: 'Sparkling Water 12oz 24pk' },
    { id: 'FG-1002', desc: 'Cold Brew 11oz 12pk' },
    { id: 'FG-2040', desc: 'Electrolyte Drink 20oz 24pk' },
    { id: 'FG-3310', desc: 'Oat Milk 32oz 6pk' },
];
const pick = a => a[Math.floor(Math.random() * a.length)];
const ymd = d => d.toISOString().slice(0, 10).replace(/-/g, '');

function idoc(bad) {
    const seq = (global.get('sim_idoc_seq') || 4500120000) + 1;
    global.set('sim_idoc_seq', seq);
    const c = pick(CUSTOMERS);
    const n = 1 + Math.floor(Math.random() * 3);
    const mats = [...MATERIALS].sort(() => Math.random() - 0.5).slice(0, n);
    const req = new Date(Date.now() + (2 + Math.floor(Math.random() * 5)) * 86400000);
    const doc = { IDOC: {
        EDI_DC40: { DOCNUM: String(seq).padStart(16, '0'), IDOCTYP: 'ORDERS05', MESTYP: 'ORDERS', SNDPRN: 'SAPECC_PRD', CREDAT: ymd(new Date()) },
        E1EDK01: { BELNR: 'PO-' + seq, CURCY: 'USD' },
        E1EDKA1: [{ PARVW: 'AG', PARTN: c.id, NAME1: c.name }],
        E1EDK03: [{ IDDAT: '002', DATUM: ymd(req) }],
        E1EDP01: mats.map((m, i) => ({
            POSEX: String((i + 1) * 10).padStart(6, '0'),
            MENGE: (20 * (1 + Math.floor(Math.random() * 12))).toFixed(3),
            MENEE: 'CS',
            E1EDP19: [{ QUALF: '002', IDTNR: m.id, KTEXT: m.desc }],
        })),
    } };
    if (bad) {                       // what a bad user-exit in SAP looks like downstream
        doc.IDOC.E1EDP01[0].E1EDP19 = [];
        doc.IDOC.E1EDP01[0].MENGE = '12,5O';
    }
    return { topic: 'erp/idoc', payload: doc };
}

const count = msg.topic === 'burst' ? 10 : 1;
const out = [];
for (let i = 0; i < count; i++) out.push(idoc(msg.topic === 'malformed'));
global.set('sim_idocs_sent', (global.get('sim_idocs_sent') || 0) + count);
return [out];

// Mock 3PL fulfilment API. The control panel can take it down.
const calls = (global.get('sim_3pl_calls') || 0) + 1;
global.set('sim_3pl_calls', calls);
if (global.get('sim_3pl_down')) {
    msg.statusCode = 503;
    msg.payload = { error: 'Service Unavailable', detail: 'upstream carrier gateway timeout' };
    return msg;
}
const body = msg.payload || {};
if (!body.orderId) {
    msg.statusCode = 400;
    msg.payload = { error: 'orderId is required' };
    return msg;
}
const carriers = ['UPS Freight', 'XPO Logistics', 'Estes Express', 'Old Dominion'];
msg.statusCode = 201;
msg.payload = {
    shipmentId: 'SHP-' + Math.random().toString(36).slice(2, 8).toUpperCase(),
    orderId: body.orderId,
    carrier: carriers[Math.floor(Math.random() * carriers.length)],
    eta: new Date(Date.now() + 2 * 86400000).toISOString().slice(0, 10),
};
return msg;

// One telemetry batch per 5 s. Offline units simply do not report.
const units = global.get('sim_units');
const now = Date.now();
const batch = [];
for (const u of Object.values(units)) {
    if (!u.forcedOffline && !u.offlineUntil && Math.random() < 0.004) u.offlineUntil = now + 20000 + Math.random() * 25000;
    if (u.offlineUntil && now > u.offlineUntil) u.offlineUntil = 0;
    if (u.forcedOffline || u.offlineUntil) continue;

    let status = 'running';
    if (u.pending) {
        if (!u.pending.landAt) u.pending.landAt = now + 3000 + Math.random() * 10000;   // lands once it can talk
        if (now >= u.pending.landAt) { u.version = u.pending.version; u.pending = null; u.bootedAt = now; }
        else status = 'updating';
    }
    u.rssi = Math.max(-115, Math.min(-55, u.rssi + Math.round((Math.random() - 0.5) * 4)));
    u.battery = Math.max(20, u.battery - (Math.random() < 0.02 ? 1 : 0));
    u.psi += (500 - u.psi) * 0.1 + (Math.random() - 0.5) * 6;

    const v24 = u.version === 'v2.4.0';
    const broken = v24 && u.board === 'rev A';
    batch.push({
        unit: u.unit, region: u.region, version: u.version, board: u.board, status,
        rssi: u.rssi, battery: u.battery,
        pressurePsi: broken ? null : Math.round(u.psi * 10) / 10,
        bytesPerMsg: Math.round(v24 ? 380 + Math.random() * 30 : 1400 + Math.random() * 60),
        errorsPerMin: broken ? 30 + Math.round(Math.random() * 12) : 0,
        lastError: broken ? 'sensor decode: unsupported frame format (board rev A)' : '',
        uptimeS: Math.round((now - u.bootedAt) / 1000),
    });
}
return { topic: 'field/telemetry', payload: batch };

