if (!global.get('sim_units')) {
    const units = {};
    for (let i = 1; i <= 24; i++) {
        const id = 'FU-' + String(i).padStart(3, '0');
        const region = i <= 10 ? 'Permian Basin, TX' : i <= 18 ? 'Bakken, ND' : 'Marcellus, PA';
        units[id] = {
            unit: id, region, version: 'v2.3.0', board: (i === 17) ? 'rev A' : 'rev C',
            rssi: -68 - Math.round(Math.random() * 30), battery: 82 + Math.round(Math.random() * 17),
            psi: 480 + Math.random() * 40, offlineUntil: 0, forcedOffline: false,
            pending: null, bootedAt: Date.now() - Math.round(Math.random() * 9e8),
        };
    }
    global.set('sim_units', units);
}

