// Rollout commands from the Fleet instance: {action:'deploy', version, units:[..]}
const units = global.get('sim_units');
const { action, version, units: targets } = msg.payload || {};
if (action !== 'deploy' || !version || !Array.isArray(targets)) return null;
let n = 0;
for (const id of targets) {
    const u = units[id];
    if (!u || u.version === version) continue;
    u.pending = { version, landAt: 0 };
    n++;
}
node.status({ fill: 'blue', shape: 'dot', text: `${version} -> ${n} units` });
return null;

// One switch for every presenter action.
const a = msg.payload && msg.payload.action;
const plants = global.get('sim_plants') || {};
const units = global.get('sim_units') || {};
const log = s => node.status({ fill: 'green', shape: 'dot', text: s });
switch (a) {
    case 'jam_p07': if (plants.P07) plants.P07.forced = 'jam'; log('Plant 7 jammed'); break;
    case 'starve_p03': if (plants.P03) plants.P03.forced = 'starve'; log('Plant 3 starved'); break;
    case 'clear_plants': Object.values(plants).forEach(p => { p.state = 1; p.fault = 0; p.idleUntil = 0; }); log('plants cleared'); break;
    case 'burst': log('order burst'); return [{ topic: 'burst' }, null];
    case 'malformed': log('malformed IDoc'); return [{ topic: 'malformed' }, null];
    case '3pl_down': global.set('sim_3pl_down', true); log('3PL down'); break;
    case '3pl_up': global.set('sim_3pl_down', false); log('3PL up'); break;
    case 'fu009_off': if (units['FU-009']) units['FU-009'].forcedOffline = true; log('FU-009 offline'); break;
    case 'fu009_on': if (units['FU-009']) units['FU-009'].forcedOffline = false; log('FU-009 online'); break;
    case 'reset_fleet':
        Object.values(units).forEach(u => { u.version = 'v2.3.0'; u.pending = null; u.forcedOffline = false; u.offlineUntil = 0; });
        log('fleet reset to v2.3.0'); break;
    default: return null;
}
return [null, null];

const plants = global.get('sim_plants') || {};
const units = Object.values(global.get('sim_units') || {});
const S = { 0: 'STOPPED', 1: 'RUNNING', 2: 'IDLE', 3: 'FAULTED' };
return { payload: {
    plants: Object.values(plants).map(p => ({ site: p.site, state: S[p.state], speed: Math.round(p.speed), fault: p.fault, map: p.map })),
    tpl: global.get('sim_3pl_down') ? 'DOWN' : 'UP',
    tplCalls: global.get('sim_3pl_calls') || 0,
    idocs: global.get('sim_idocs_sent') || 0,
    online: units.filter(u => !u.forcedOffline && !u.offlineUntil).length,
    total: units.length,
    versions: units.reduce((m, u) => (m[u.version] = (m[u.version] || 0) + 1, m), {}),
    pending: units.filter(u => u.pending).length,
} };
